// SigV4, pinned against vectors this code did not produce. A signer that agrees with its own
// idea of the algorithm proves nothing, and the failure it would hide — a signature the service
// rejects as a bare 403 — is the least diagnosable one in the file.
//
// The first case is `get-vanilla` from AWS's published aws-sig-v4-test-suite, verbatim. The S3
// case below is not in that suite (it covers a generic service, not S3's extra header), so it
// was generated by an independent implementation of the specification — one that reproduces
// `get-vanilla` exactly, which is what makes it worth trusting for the case the suite omits.
//
// Real acceptance is proved elsewhere and has to be: only an S3 implementation can say whether
// it likes a signature. The compose stack runs the forge against MinIO for that.

import { test } from "bun:test";
import { assertEquals } from "@std/assert";
import { encodeSegment, sha256Hex, signRequest } from "../src/helpers/sigv4.ts";

// The credentials and instant every vector in that suite uses.
const CREDS = {
  accessKeyId: "AKIDEXAMPLE",
  secretAccessKey: "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY",
  region: "us-east-1",
  service: "service",
};
const WHEN = new Date("2015-08-30T12:36:00Z");
const EMPTY_BODY = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

test("sigv4: get-vanilla matches AWS's published signature", async () => {
  const signed = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { host: "example.amazonaws.com" },
      payloadHash: EMPTY_BODY,
    },
    CREDS,
    WHEN,
  );

  assertEquals(signed["x-amz-date"], "20150830T123600Z");
  assertEquals(
    signed.authorization,
    "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20150830/us-east-1/service/aws4_request, " +
      "SignedHeaders=host;x-amz-date, " +
      "Signature=5fa00fa31553b73ebf1942676e86291e8372ff2a2260956d9b8aae1d763fbf31",
  );
});

test("sigv4: every caller-supplied header is signed, in the S3 scope", async () => {
  // x-amz-content-sha256 is passed in by the caller rather than added by the signer, so it lands
  // in SignedHeaders like any other header. content-length is here to prove that generality —
  // NOT because `put` sends it: it is a forbidden header that fetch would drop, and signing a
  // header the socket never sends is a 403 with no explanation. See the adapter.
  const signed = await signRequest(
    {
      method: "PUT",
      path: "/ryph-patches/patches/r-1/bundle.pack",
      headers: {
        host: "s3.eu-central-1.amazonaws.com",
        "content-length": "1234",
        "x-amz-content-sha256": EMPTY_BODY,
      },
      payloadHash: EMPTY_BODY,
    },
    { ...CREDS, region: "eu-central-1", service: "s3" },
    WHEN,
  );

  assertEquals(
    signed.authorization,
    "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20150830/eu-central-1/s3/aws4_request, " +
      "SignedHeaders=content-length;host;x-amz-content-sha256;x-amz-date, " +
      "Signature=c68600743f1d54182d1b32328bfbff23f57887ed8ee9f586c202719a46a23336",
  );
});

test("sigv4: the empty-body hash is the constant every S3 request sends", async () => {
  assertEquals(await sha256Hex(""), EMPTY_BODY);
});

test("sigv4: header values are trimmed and inner whitespace collapsed", async () => {
  // get-header-value-trim, from the same suite: signing the raw value would disagree with what
  // the service canonicalises before checking.
  const padded = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { host: "example.amazonaws.com", "my-header1": "  value1  " },
      payloadHash: EMPTY_BODY,
    },
    CREDS,
    WHEN,
  );
  const tight = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { host: "example.amazonaws.com", "my-header1": "value1" },
      payloadHash: EMPTY_BODY,
    },
    CREDS,
    WHEN,
  );
  assertEquals(padded.authorization, tight.authorization);
});

test("sigv4: header names are case-insensitive and sorted", async () => {
  const shouted = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { "MY-HEADER1": "value1", HOST: "example.amazonaws.com" },
      payloadHash: EMPTY_BODY,
    },
    CREDS,
    WHEN,
  );
  const quiet = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { host: "example.amazonaws.com", "my-header1": "value1" },
      payloadHash: EMPTY_BODY,
    },
    CREDS,
    WHEN,
  );
  assertEquals(shouted.authorization, quiet.authorization);
});

test("sigv4: a session token is signed, not merely sent", async () => {
  const withToken = await signRequest(
    {
      method: "GET",
      path: "/",
      headers: { host: "example.amazonaws.com" },
      payloadHash: EMPTY_BODY,
    },
    { ...CREDS, sessionToken: "session-token-value" },
    WHEN,
  );

  assertEquals(withToken["x-amz-security-token"], "session-token-value");
  // If it were merely sent, SignedHeaders would not name it and the service would reject.
  assertEquals(withToken.authorization.includes("x-amz-security-token"), true);
});

test("sigv4: path encoding follows the unreserved set, not encodeURIComponent's", () => {
  // The two disagree on exactly these, and a key containing one is where a hand-rolled signer
  // silently starts producing signature mismatches.
  assertEquals(encodeSegment("a b"), "a%20b");
  assertEquals(encodeSegment("plus+sign"), "plus%2Bsign");
  assertEquals(encodeSegment("tilde~dash-dot.under_"), "tilde~dash-dot.under_");
  assertEquals(encodeSegment("star*"), "star%2A");
  assertEquals(encodeSegment("paren()"), "paren%28%29");
  assertEquals(encodeSegment("quote'"), "quote%27");
  assertEquals(encodeSegment("bang!"), "bang%21");
  // Multi-byte input is encoded per UTF-8 byte, uppercase hex.
  assertEquals(encodeSegment("é"), "%C3%A9");
});
